from odoo import fields, models
from odoo.tools import float_is_zero

NUMERIC_TYPES = ("integer", "float", "monetary")


def format_zero(field, value):
    """How the ECD writes a numeric field that is zero, or None if not zero.

    A mandatory zero is written as ``0`` (the PVA refuses the I155 with a
    blank VL_DEB, or the 0000 with a blank TIP_ECD); an optional one stays
    blank.
    """
    if field.type not in NUMERIC_TYPES:
        return None
    if not float_is_zero(value or 0.0, precision_digits=8):
        return None
    if field.required or getattr(field, "out_required", False):
        return "0"
    return ""


